    /// <summary>取某资产里的某函数；找不到返回 null（绝不静默当成空操作）。</summary>
    public static Func<IHost, Val, Val[], Val> Find(string asset, string fn)
        => Assets.TryGetValue(asset, out var m) && m.TryGetValue(fn, out var f) ? f : null;

